mapper.select:
WITH requested(user_id) AS ( VALUES
(#{userId})
) SELECT encode(u.id, 'hex') AS "id", u.user_id AS "userId", encode(u.coupon_template_id, 'hex') AS "couponTemplateId", u.status, u.valid_start_at AS "validStartAt", u.valid_end_at AS "validEndAt", u.received_at AS "receivedAt", u.locked_order_no AS "lockedOrderNo", u.locked_at AS "lockedAt", u.used_order_no AS "usedOrderNo", u.used_at AS "usedAt", u.version, u.created_at AS "createdAt", u.updated_at AS "updatedAt" FROM user_coupon u INNER JOIN requested r ON r.user_id = u.user_id
WHERE u.status = #{status}
ORDER BY u.received_at DESC, u.created_at DESC

WITH template_state AS ( SELECT EXISTS ( SELECT 1 FROM coupon_template WHERE id = #{couponTemplateId} ) AS template_exists ), filtered_claims AS ( SELECT encode(uc.id, 'hex') AS "userCouponId", encode(uc.coupon_template_id, 'hex') AS "couponTemplateId", uc.user_id AS "userId", uli.email AS email, uc.status AS status, uc.received_at AS "receivedAt", uc.valid_start_at AS "validStartAt", uc.valid_end_at AS "validEndAt", uc.locked_order_no AS "lockedOrderNo", uc.locked_at AS "lockedAt", uc.used_order_no AS "usedOrderNo", uc.used_at AS "usedAt", uc.created_at AS "createdAt" FROM user_coupon uc LEFT JOIN user_login_identity uli ON uli.user_id = uc.user_id WHERE uc.coupon_template_id = #{couponTemplateId}
AND uc.status = #{status}
AND uli.email = #{email}
), claim_count AS ( SELECT COUNT(*) AS total FROM filtered_claims ), paged_claims AS ( SELECT * FROM filtered_claims ORDER BY "receivedAt" DESC, "createdAt" DESC LIMIT #{pageSize} OFFSET #{offset} ) SELECT ts.template_exists AS "templateExists", cc.total AS "total", pc."userCouponId", pc."couponTemplateId", pc."userId", pc.email, pc.status, pc."receivedAt", pc."validStartAt", pc."validEndAt", pc."lockedOrderNo", pc."lockedAt", pc."usedOrderNo", pc."usedAt" FROM template_state ts CROSS JOIN claim_count cc LEFT JOIN paged_claims pc ON TRUE

SELECT 
FROM user_coupon uc
INNER JOIN coupon_template ct ON ct.id = uc.coupon_template_id
WHERE uc.user_id = #{userId}

    AND uc.status = #{status}

ORDER BY uc.received_at DESC, uc.created_at DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM user_coupon uc
WHERE uc.user_id = #{userId}

    AND uc.status = #{status}

SELECT 
FROM user_coupon uc
INNER JOIN coupon_template ct ON ct.id = uc.coupon_template_id
WHERE uc.user_id = #{userId}
  AND uc.id = #{userCouponId}

SELECT 
FROM user_coupon uc
INNER JOIN coupon_template ct ON ct.id = uc.coupon_template_id
WHERE uc.user_id = #{userId}
  AND uc.id = #{userCouponId}
